/*
 * ADAM — القوانين والمقاسات الرسمية لكل رياضة
 * Official rules & dimensions per sport (kind: rules, prefix rl_).
 *
 * One entry per sport id in sports.js (except 'general' and 'other_sport').
 * Values come from the governing-body rulebook named in `source`.
 * When a value differs by competition level, the value says so.
 * Validate with:  node tools/check-hub.js rules library/sport-rules.js
 */

/* item: label + value, each { ar, en } */
const i = (lAr, lEn, vAr, vEn) => ({ label: { ar: lAr, en: lEn }, value: { ar: vAr, en: vEn } });
/* section */
const s = (id, ...items) => ({ id, items });
/* rule entry */
const r = (sport, source, ...sections) => ({ id: 'rl_' + sport, sport, source, sections });

